// Every panel in the working dataset is named VESSEL_<prefix>_... and lives under
// references/<paper-slug>/figures/panels/. The px -> um scale is measured from the scale bar
// the figure prints and tabulated as SCALEBAR_PX in the extraction script, keyed by panel-name
// prefix (longest match wins) so one figure can calibrate rows that differ in zoom.
//
// A panel may instead carry its scale DIRECTLY, in UMPP_DIRECT, when the source image's own
// metadata states um/px and no bar is involved — stronger evidence than a measured bar.
//
// A panel whose scale genuinely cannot be measured — the figure draws no bar — is not a
// violation, but it must SAY so: an entry in UNCALIBRATED, carrying the reason. The point of
// this rule is that no panel is uncalibrated by accident.
const PANEL = /^references\/[^/]+\/figures\/panels\/VESSEL_(.+)\.png$/i;
const MEASURE = 'analysis/measure_vessels.py';
const TABLE = /SCALEBAR_PX\s*=\s*\{([\s\S]*?)\}/;
const DIRECT = /UMPP_DIRECT\s*=\s*\{([\s\S]*?)\n\}/;
const DECLARED = /UNCALIBRATED\s*=\s*\{([\s\S]*?)\n\}/;

// The wang-2022 panels carry a channel suffix the calibration keys never include.
const stripSuffix = (s) => s.replace(/_gP-CD31_red$/, '');

const keysOf = (block) => (block ? [...block.matchAll(/['"]([^'"]+)['"]\s*:/g)].map((m) => m[1]) : []);

const rule = {
  id: 'panel-scale-calibration',
  severity: 'blocking',
  description: 'Every working panel is either scale-calibrated or declared uncalibrated',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an uncalibrated figure does not fail — it silently reports "um n/a" and drops out of every length and density number, so a panel added without its bar measurement quietly shrinks the result set',

  run(ctx) {
    const text = ctx.read(MEASURE);
    if (text === null) return [];
    const lines = text.split('\n');
    const lineOf = (needle) => lines.findIndex((l) => l.includes(needle)) + 1 || null;
    const m = TABLE.exec(text);
    if (!m) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: null,
        what: 'no SCALEBAR_PX table found',
        why: rule.why,
        fix: 'keep the per-prefix scale-bar widths in a SCALEBAR_PX = { ... } table in this file — it is the single calibration source annotate_overlays.py imports',
        doc: rule.doc,
      }];
    }
    const calibrated = keysOf(m[1]);
    const direct = keysOf(DIRECT.exec(text)?.[1]);
    const declared = keysOf(DECLARED.exec(text)?.[1]);
    const covers = (name) => [...calibrated, ...direct, ...declared].some((k) => name.startsWith(k));

    const panels = new Set();
    for (const f of ctx.tracked) {
      const hit = PANEL.exec(f);
      if (hit) panels.add(stripSuffix(hit[1]));
    }
    return [...panels].sort()
      .filter((name) => !covers(name))
      .map((name) => ({
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: lineOf('SCALEBAR_PX'),
        what: `VESSEL_${name} matches no SCALEBAR_PX, UMPP_DIRECT or UNCALIBRATED prefix`,
        why: rule.why,
        fix: `measure the scale bar printed on that panel's row and add a '<prefix>': <bar width in px> entry to SCALEBAR_PX (plus SCALEBAR_UM if the bar is not 50 um); or, if the source image states its own um/px, put it in UMPP_DIRECT with its provenance; or, if the figure draws no bar at all, add the prefix to UNCALIBRATED with the reason`,
        doc: rule.doc,
      }));
  },
};

export default rule;

content.content:
1	// The px -> um scale of every figure is derived from ONE source: UM_PER_BAR /
2	// SCALEBAR_PX in the extraction script (the measured 50 um bar widths). The docs
3	// quote those numbers in three places (the pack RULES, the working guide, the
4	// results calibration table) — this check keeps the copies honest.
5	//
6	// Detection is column/label-scoped, never a bare grep for decimals: a claim is
7	// read only from an inline `figN = <value>` in a passage that says "um/px", or
8	// from a markdown table's own um/px and bar-width COLUMNS, and only when the
9	// figure cell names a figure rather than a panel. That is what keeps the per-panel
10	// results table (fig1_C1_healthy | 2145 | 23.6 | ...) out of scope.
11	const MEASURE = 'analysis/measure_vessels.py';
12	const SKIP = '.claudinite/shared/';                 // read-only mounted canon
13	const UM_PER_BAR = /UM_PER_BAR\s*=\s*([\d.]+)/;
14	const TABLE = /SCALEBAR_PX\s*=\s*\{([^}]*)\}/;
15	
16	const MU = '[µμu]';                       // micro sign / greek mu / plain "u"
17	const MU_LABEL = 'µm/px';
18	const UMPP = new RegExp(`${MU}m\\s*/\\s*px`, 'i');  // the unit that marks a scale claim
19	// "fig1 = 0.820", "fig4/5/6 = 0.658", "fig4 / fig5 = 0.658"
20	const INLINE = /\bfig(\d+(?:\s*\/\s*(?:fig)?\d+)*)\s*=\s*\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)/g;
21	// a table cell that is just a number, optionally in px and/or bold: "61 px", "**0.820**"
22	const NUM_CELL = /^\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)\s*(?:px)?\s*\*{0,2}$/;
23	
24	// The figures a label names — "fig1", "fig4/5/6", "fig4 / fig5". Anything that is
25	// not a bare figure number is dropped, so a panel-level label ("fig1_C1_healthy",
26	// "fig1 crop A2") names no figure and carries no claim.
27	const figsOf = (labels) => labels
28	  .split(/[/,]/)
29	  .map((p) => p.trim().replace(/^fig/i, ''))
30	  .filter((p) => /^\d+$/.test(p))
31	  .map((p) => `fig${p}`);
32	
33	// A quoted value agrees if it matches the true value rounded to the precision the
34	// doc chose to quote it at (0.820, 0.82 and 0.8197 all describe 50/61).
35	const agrees = (quoted, truth) => {
36	  const dp = (quoted.split('.')[1] || '').length;
37	  return Number(quoted) === Number(truth.toFixed(dp));
38	};
39	
40	const cells = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
41	
42	// Blank-line-separated blocks, with the 1-based line each block starts on.
43	const blocks = (text) => {
44	  const out = [];
45	  let cur = null;
46	  text.split('\n').forEach((line, i) => {
47	    if (line.trim() === '') { cur = null; return; }
48	    if (!cur) { cur = { start: i + 1, lines: [] }; out.push(cur); }
49	    cur.lines.push(line);
50	  });
51	  return out;
52	};
53	
54	const rule = {
55	  id: 'scale-numbers-match-calibration',
56	  severity: 'blocking',
57	  description: 'Scale numbers quoted in the docs match the SCALEBAR_PX calibration',
58	  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
59	  why: 'the um/px per figure is derived from one measured table (UM_PER_BAR / SCALEBAR_PX); a doc that quotes a stale copy does not fail loudly — it silently re-labels every length and density number in that document with the wrong scale',
60	
61	  run(ctx) {
62	    const src = ctx.read(MEASURE);
63	    if (src === null) return [];
64	    const perBar = UM_PER_BAR.exec(src);
65	    const table = TABLE.exec(src);
66	    // No calibration source to compare against: panel-scale-calibration owns that.
67	    if (!perBar || !table) return [];
68	    const bar = new Map(
69	      [...table[1].matchAll(/['"]([^'"]+)['"]\s*:\s*(\d+(?:\.\d+)?)/g)].map((m) => [m[1], Number(m[2])]),
70	    );
71	    const um = Number(perBar[1]);
72	    const truth = (fig, kind) => {
73	      const px = bar.get(fig);
74	      if (px === undefined) return null;               // uncalibrated figure -> not this rule
75	      return kind === 'bar' ? px : um / px;
76	    };
77	
78	    const out = [];
79	    const flag = (file, line, fig, kind, quoted, expected) => out.push({
80	      rule: rule.id,
81	      severity: rule.severity,
82	      file,
83	      line,
84	      what: kind === 'bar'
85	        ? `${fig}'s scale bar is quoted as ${quoted} px but SCALEBAR_PX says ${expected}`
86	        : `${fig}'s scale is quoted as ${quoted} ${MU_LABEL} but SCALEBAR_PX gives ${expected}`,
87	      why: rule.why,
88	      fix: kind === 'bar'
89	        ? `quote ${fig}'s bar as ${expected} px, or fix SCALEBAR_PX in ${MEASURE} if the measurement changed — the table is the single source`
90	        : `quote ${expected} ${MU_LABEL} for ${fig} (UM_PER_BAR / SCALEBAR_PX['${fig}']), or fix the table in ${MEASURE} if the measurement changed`,
91	      doc: rule.doc,
92	    });
93	
94	    for (const file of ctx.tracked) {
95	      if (!file.endsWith('.md') || file.startsWith(SKIP)) continue;
96	      const text = ctx.read(file);
97	      if (text === null) continue;
98	
99	      for (const blk of blocks(text)) {
100	        const body = blk.lines.join('\n');
101	        if (!UMPP.test(body)) continue;               // no scale claim in this passage
102	
103	        // --- inline prose claims: "fig1 = 0.820" ---------------------------
104	        blk.lines.forEach((line, i) => {
105	          if (line.trim().startsWith('|')) return;    // table rows handled below
106	          for (const m of line.matchAll(INLINE)) {
107	            for (const fig of figsOf(m[1])) {
108	              const t = truth(fig, 'umpp');
109	              if (t === null) continue;
110	              if (!agrees(m[2], t)) flag(file, blk.start + i, fig, 'umpp', m[2], t.toFixed(3));
111	            }
112	          }
113	        });
114	
115	        // --- table columns: a um/px column and/or a bar-width column -------
116	        const rows = blk.lines.map((l, i) => ({ line: blk.start + i, raw: l }))
117	          .filter((r) => r.raw.trim().startsWith('|'));
118	        if (rows.length < 3) continue;
119	        const head = cells(rows[0].raw);
