1	// The px -> um scale of every figure comes from ONE measured table: UM_PER_BAR
2	// and SCALEBAR_PX in analysis/measure_vessels.py. annotate_overlays.py reads them
3	// by importing from there, never by carrying its own copy — that is the invariant
4	// this check holds.
5	//
6	// Companion to scale-numbers-match-calibration, which holds the numbers quoted in
7	// *markdown* to that table. Markdown is all that check reads, so a second table
8	// defined in Python is invisible to it: the two rules cover opposite halves of the
9	// same single-source line.
10	//
11	// Parse rather than grep: the names are stripped of comments and of every string
12	// literal (including the docstrings that spell the table out) first, and only an
13	// assignment — `NAME =`, or an annotated `NAME: dict =` — counts. A docstring
14	// quoting "SCALEBAR_PX = {'fig1': 61}" documents the table; it does not define it.
15	const SOURCE = 'analysis/measure_vessels.py';
16	const SHARED = '.claudinite/shared/';        // read-only mounted canon
17	const CALIBRATION = ['UM_PER_BAR', 'SCALEBAR_PX'];
18	const ASSIGN = new RegExp(`^\\s*(${CALIBRATION.join('|')})\\s*(?::[^=\\n]+)?=(?!=)`);
19	
20	// Blank out comments and string literals, keeping every newline and every column
21	// so line numbers and the assignment shape survive. Handles ''' / """ blocks,
22	// single-quoted strings and escapes; a `#` inside a string is not a comment.
23	function code(text) {
24	  const out = [];
25	  let i = 0;
26	  let quote = null;                          // the open delimiter, or null
27	  while (i < text.length) {
28	    const c = text[i];
29	    if (quote) {
30	      if (c === '\\' && quote.length === 1) { out.push(' ', ' '); i += 2; continue; }
31	      if (text.startsWith(quote, i)) {
32	        out.push(' '.repeat(quote.length));
33	        i += quote.length;
34	        quote = null;
35	        continue;
36	      }
37	      out.push(c === '\n' ? '\n' : ' ');
38	      i += 1;
39	      continue;
40	    }
41	    if (c === '#') {                         // to end of line
42	      while (i < text.length && text[i] !== '\n') { out.push(' '); i += 1; }
43	      continue;
44	    }
45	    if (c === '"' || c === "'") {
46	      quote = text.startsWith(c.repeat(3), i) ? c.repeat(3) : c;
47	      out.push(' '.repeat(quote.length));
48	      i += quote.length;
49	      continue;
50	    }
51	    out.push(c);
52	    i += 1;
53	  }
54	  return out.join('');
55	}
56	
57	// Every line of `text` that assigns one of the calibration names, as { name, line }.
58	// Only statements count: a line that starts inside an open bracket is a continuation,
59	// where `UM_PER_BAR=50` is a keyword argument being passed, not the table being defined.
60	function definitions(text) {
61	  const out = [];
62	  let depth = 0;
63	  code(text).split('\n').forEach((line, i) => {
64	    const hit = depth === 0 ? ASSIGN.exec(line) : null;
65	    if (hit) out.push({ name: hit[1], line: i + 1 });
66	    for (const c of line) {
67	      if ('([{'.includes(c)) depth += 1;
68	      else if (')]}'.includes(c)) depth = Math.max(0, depth - 1);
69	    }
70	  });
71	  return out;
72	}
73	
74	const rule = {
75	  id: 'calibration-single-source',
76	  severity: 'blocking',
77	  description: 'The scale-bar calibration is defined only in the extraction script',
78	  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
79	  why: 'UM_PER_BAR / SCALEBAR_PX are a measurement, not a constant — a second definition means two calibrations, and the one a given script happens to read wins silently, re-labelling its lengths and densities with a scale nobody re-measured',
80	
81	  run(ctx) {
82	    const out = [];
83	    const flag = (file, line, what, fix) => out.push({
84	      rule: rule.id, severity: rule.severity, file, line, what, why: rule.why, fix, doc: rule.doc,
85	    });
86	
87	    for (const file of ctx.tracked) {
88	      if (!file.endsWith('.py') || file.startsWith(SHARED)) continue;
89	      const text = ctx.read(file);
90	      if (text === null) continue;
91	      const defs = definitions(text);
92	
93	      if (file === SOURCE) {
94	        // The source file itself: a name assigned twice is the same drift, one
95	        // file in. The later assignment wins and the earlier measurement is dead
96	        // code that still reads as the calibration.
97	        for (const name of CALIBRATION) {
98	          const mine = defs.filter((d) => d.name === name);
99	          if (mine.length < 2) continue;
100	          flag(file, mine[mine.length - 1].line,
101	            `${name} is assigned ${mine.length} times in ${SOURCE} (lines ${mine.map((d) => d.line).join(', ')})`,
102	            `keep one ${name} assignment — delete the copies, or if the bar was re-measured, replace the single definition with the new value`);
103	        }
104	        continue;
105	      }
106	
107	      for (const def of defs) {
108	        flag(file, def.line,
109	          `${file} defines its own ${def.name}`,
110	          `import it instead — \`from measure_vessels import ${def.name}\`, the way the overlay script already reads the table; if a bar really was re-measured, change the value in ${SOURCE}, the one place it is measured`);
111	      }
112	    }
113	    return out;
114	  },
115	};
116	
117	export default rule;
